astDayOfMonth = DateUtil.lastDayOfMonth(month, year);</p>\n<h3>91     if (day > lastDayOfMonth)</h3>\n<p>395Appendix B: org.jfree.date.SerialDate 92         day = lastDayOfMonth; 93     return day; 94   } 96   public DayDate getPreviousDayOfWeek(Day targetDayOfWeek) { 97     int offsetToTarget = targetDayOfWeek.toInt() - getDayOfWeek().toInt(); 98     if (offsetToTarget >= 0) 99       offsetToTarget -= 7; 100     return plusDays(offsetToTarget); 101   } 103   public DayDate getFollowingDayOfWeek(Day targetDayOfWeek) { 104     int offsetToTarget = targetDayOfWeek.toInt() - getDayOfWeek().toInt(); 105     if (offsetToTarget <= 0) 106       offsetToTarget += 7; 107     return plusDays(offsetToTarget); 108   } 110   public DayDate getNearestDayOfWeek(Day targetDayOfWeek) { 111     int offsetToThisWeeksTarget = targetDayOfWeek.toInt() - getDayOfWeek().toInt(); 112     int offsetToFutureTarget = (offsetToThisWeeksTarget + 7) % 7; 113     int offsetToPreviousTarget = offsetToFutureTarget - 7; 115     if (offsetToFutureTarget > 3) 116       return plusDays(offsetToPreviousTarget); 117     else 118       return plusDays(offsetToFutureTarget); 119   } 121   public DayDate getEndOfMonth() {</p>\n<h3>122     Month month = getMonth();</h3>\n<p>123     int year = getYear(); 124     int lastDay = DateUtil.lastDayOfMonth(month, year); 125     return DayDateFactory.makeDate(lastDay, month, year); 126   } 128   public Date toDate() { 129     final Calendar calendar = Calendar.getInstance(); 130     int ordinalMonth = getMonth().toInt() - Month.JANUARY.toInt(); 131     calendar.set(getYear(), ordinalMonth, getDayOfMonth(), 0, 0, 0); 132     return calendar.getTime(); 133   } 135   public String toString() { 136     return String.format("%02d-%s-%d", getDayOfMonth(), getMonth(), getYear()); 137   } 139   public Day getDayOfWeek() {</p>\n<h3>140     Day startingDay = getDayOfWeekForOrdinalZero();</h3>\n<p>141     int startingOffset = startingDay.toInt() - Day.SUNDAY.toInt(); 142     int ordinalOfDayOfWeek = (getOrdinalDay() + startingOffset) % 7; 143     return Day.fromInt(ordinalOfDayOfWeek + Day.SUNDAY.toInt()); 144   } 146   public int daysSince(DayDate date) { 147     return getOrdinalDay() - date.getOrdinalDay(); 148   } 150   public boolean isOn(DayDate other) { 151     return getOrdinalDay() == other.getOrdinalDay(); 152   } Listing B-7 (continued)</p>\n<h3>DayDate.java (Final)</h3>\n<p>396Appendix B: org.jfree.date.SerialDate 154   public boolean isBefore(DayDate other) { 155     return getOrdinalDay() < other.getOrdinalDay(); 156   } 158   public boolean isOnOrBefore(DayDate other) { 159     return getOrdinalDay() <= other.getOrdinalDay(); 160   } 162   public boolean isAfter(DayDate other) { 163     return getOrdinalDay() > other.getOrdinalDay(); 164   } 166   public boolean isOnOrAfter(DayDate other) { 167     return getOrdinalDay() >= other.getOrdinalDay(); 168   } 170   public boolean isInRange(DayDate d1, DayDate d2) { 171     return isInRange(d1, d2, DateInterval.CLOSED); 172   } 174   public boolean isInRange(DayDate d1, DayDate d2, DateInterval interval) { 175     int left = Math.min(d1.getOrdinalDay(), d2.getOrdinalDay()); 176     int right = Math.max(d1.getOrdinalDay(), d2.getOrdinalDay()); 177     return interval.isIn(getOrdinalDay(), left, right); 178   } 179 } Listing B-7 (continued)</p>\n<h3>DayDate.java (Final)</h3>\n<p>397Appendix B: org.jfree.date.SerialDate Listing B-8 Month.java (Final) 1 package org.jfree.date; 3 import java.text.DateFormatSymbols; 5 public enum Month {</p>\n<h3>6   JANUARY(1), FEBRUARY(2), MARCH(3),</h3>\n<h3>7   APRIL(4),   MAY(5),      JUNE(6),</h3>\n<h3>8   JULY(7),    AUGUST(8),   SEPTEMBER(9),</h3>\n<h3>9   OCTOBER(10),NOVEMBER(11),DECEMBER(12);</h3>\n<p>10   private static DateFormatSymbols dateFormatSymbols = new DateFormatSymbols(); 11   private static final int[] LAST_DAY_OF_MONTH = 12     {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}; 14   private int index;</p>\n<h3>16   Month(int ind