ls(1, leapYearCount(1906)); 246     assertEquals(1, leapYearCount(1907)); 247     assertEquals(2, leapYearCount(1908)); 248     assertEquals(24, leapYearCount(1999)); 249     assertEquals(25, leapYearCount(2001)); 250     assertEquals(49, leapYearCount(2101)); 251     assertEquals(73, leapYearCount(2201)); Listing B-4 (continued)</p>\n<h3>BobsSerialDateTest.java</h3>\n<p>378Appendix B: org.jfree.date.SerialDate 252     assertEquals(97, leapYearCount(2301)); 253     assertEquals(122, leapYearCount(2401)); 254   } 256   public void testLastDayOfMonth() throws Exception { 257     assertEquals(31, lastDayOfMonth(JANUARY, 1901)); 258     assertEquals(28, lastDayOfMonth(FEBRUARY, 1901)); 259     assertEquals(31, lastDayOfMonth(MARCH, 1901)); 260     assertEquals(30, lastDayOfMonth(APRIL, 1901)); 261     assertEquals(31, lastDayOfMonth(MAY, 1901)); 262     assertEquals(30, lastDayOfMonth(JUNE, 1901)); 263     assertEquals(31, lastDayOfMonth(JULY, 1901)); 264     assertEquals(31, lastDayOfMonth(AUGUST, 1901)); 265     assertEquals(30, lastDayOfMonth(SEPTEMBER, 1901)); 266     assertEquals(31, lastDayOfMonth(OCTOBER, 1901)); 267     assertEquals(30, lastDayOfMonth(NOVEMBER, 1901)); 268     assertEquals(31, lastDayOfMonth(DECEMBER, 1901)); 269     assertEquals(29, lastDayOfMonth(FEBRUARY, 1904)); 270   } 272   public void testAddDays() throws Exception {</p>\n<h3>273     SerialDate newYears = d(1, JANUARY, 1900);</h3>\n<p>274     assertEquals(d(2, JANUARY, 1900), addDays(1, newYears)); 275     assertEquals(d(1, FEBRUARY, 1900), addDays(31, newYears)); 276     assertEquals(d(1, JANUARY, 1901), addDays(365, newYears)); 277     assertEquals(d(31, DECEMBER, 1904), addDays(5 * 365, newYears)); 278   } 280   private static SpreadsheetDate d(int day, int month, int year) {return new SpreadsheetDate(day, month, year);} 282   public void testAddMonths() throws Exception { 283     assertEquals(d(1, FEBRUARY, 1900), addMonths(1, d(1, JANUARY, 1900))); 284     assertEquals(d(28, FEBRUARY