se; 58 import junit.framework.TestSuite; 60 import org.jfree.date.MonthConstants; 61 import org.jfree.date.SerialDate;</p>\n<p>367Appendix B: org.jfree.date.SerialDate 63 /** 64  * Some JUnit tests for the {@link SerialDate} class. 65  */ 66 public class SerialDateTests extends TestCase { 68     /** Date representing November 9. */ 69     private SerialDate nov9Y2001; 71     /** 72      * Creates a new test case. 73      * 74      * @param name  the name. 75      */ 76     public SerialDateTests(final String name) { 77         super(name); 78     } 80     /** 81      * Returns a test suite for the JUnit test runner. 82      * 83      * @return The test suite. 84      */ 85     public static Test suite() { 86         return new TestSuite(SerialDateTests.class); 87     } 89     /** 90      * Problem set up. 91      */ 92     protected void setUp() { 93         this.nov9Y2001 = SerialDate.createInstance(9, MonthConstants.NOVEMBER, 2001); 94     } 96     /** 97      * 9 Nov 2001 plus two months should be 9 Jan 2002. 98      */ 99     public void testAddMonthsTo9Nov2001() { 100         final SerialDate jan9Y2002 = SerialDate.addMonths(2, this.nov9Y2001); 101         final SerialDate answer = SerialDate.createInstance(9, 1, 2002); 102         assertEquals(answer, jan9Y2002); 103     } 105     /** 106      * A test case for a reported bug, now fixed. 107      */ 108     public void testAddMonthsTo5Oct2003() { 109         final SerialDate d1 = SerialDate.createInstance(5, MonthConstants.OCTOBER, 2003); 110         final SerialDate d2 = SerialDate.addMonths(2, d1); 111         assertEquals(d2, SerialDate.createInstance(5, MonthConstants.DECEMBER, 2003)); 112     } 114     /** 115      * A test case for a reported bug, now fixed. 116      */ 117     public void testAddMonthsTo1Jan2003() { 118         final SerialDate d1 = SerialDate.createInstance(1, MonthConstants.JANUARY, 2003); 119         final SerialDate d2 = SerialDate.addMonths(0, d1); 120         assertEquals(d2, d1); 121     } 123     /** 124      * Monday preceding Friday 9 November 2001 should be 5 November. Listing B-2 (continued)</p>\n<h3>SerialDateTest.java</h3>\n<p>368Appendix B: org.jfree.date.SerialDate 125      */ 126     public void testMondayPrecedingFriday9Nov2001() {</p>\n<h3>127         SerialDate mondayBefore = SerialDate.getPreviousDayOfWeek(</h3>\n<h3>128             SerialDate.MONDAY, this.nov9Y2001</h3>\n<p>129         ); 130         assertEquals(5, mondayBefore.getDayOfMonth()); 131     } 133     /** 134      * Monday following Friday 9 November 2001 should be 12 November. 135      */ 136     public void testMondayFollowingFriday9Nov2001() {</p>\n<h3>137         SerialDate mondayAfter = SerialDate.getFollowingDayOfWeek(</h3>\n<h3>138             SerialDate.MONDAY, this.nov9Y2001</h3>\n<p>139         ); 140         assertEquals(12, mondayAfter.getDayOfMonth()); 141     } 143     /** 144      * Monday nearest Friday 9 November 2001 should be 12 November. 145      */ 146     public void testMondayNearestFriday9Nov2001() {</p>\n<h3>147         SerialDate mondayNearest = SerialDate.getNearestDayOfWeek(</h3>\n<h3>148             SerialDate.MONDAY, this.nov9Y2001</h3>\n<p>149         ); 150         assertEquals(12, mondayNearest.getDayOfMonth()); 151     } 153     /** 154      * The Monday nearest to 22nd January 1970 falls on the 19th. 155      */ 156     public void testMondayNearest22Jan1970() { 157         SerialDate jan22Y1970 = SerialDate.createInstance(22, MonthConstants.JANUARY, 1970); 158         SerialDate mondayNearest=SerialDate.getNearestDayOfWeek(SerialDate.MONDAY, jan22Y1970); 159         assertEquals(19, mondayNearest.getDayOfMonth()); 160     } 162     /** 163      * Problem that the conversion of days to strings returns the right result.  Actually, this 164      * result depends on the Locale so this test needs to be modified. 165      */ 166     public void testWeekdayCodeToString() { 168         final String test = SerialDate.weekdayCodeToString(SerialDate.SATURDAY); 169         assertEquals("Saturday", test); 171     } 173     /** 174      * Test the conversion of a string to a weekday.  Note that this test will fail if the 175      * default locale doesn't use English weekday names...devise a better test! 176      */ 177     public void testStringToWeekday() { 179         int weekday = SerialDate.stringToWeekdayCode("Wednesday"); 180         assertEquals(SerialDate.WEDNESDAY, weekday); 182         weekday = SerialDate.stringToWeekdayCode(" Wednesday "); 183         assertEquals(SerialDate.WEDNESDAY, weekday); Listing B-2 (continued)</p>\n<h3>SerialDateTest.java</h3>\n<p>369Appendix B: org.jfree.date.SerialDate 185         weekday = SerialDate.stringToWeekdayCode("Wed"); 186         assertEquals(SerialDate.WEDNESDAY, weekday); 188     } 190     /** 191      * Test the conversion of a string to a month.  Note that this test will fail if the 192      * default locale doesn't use English month names...devise a better test! 193      */ 194     public void testStringToMonthCode() { 196         int m = SerialDate.stringToMonthCode("January"); 197         assertEquals(MonthConstants.JANUARY, m); 199         m = SerialDate.stringToMonthCode(" January "); 200         assertEquals(MonthConstants.JANUARY, m); 202         m = SerialDate.stringToMonthCode("Jan"); 203         assertEquals(MonthConstants.JANUARY, m); 205     } 207     /** 208      * Tests the conversion of a month code to a string. 209      */ 210     public void testMonthCodeToStringCode() { 212         final String test = SerialDate.monthCodeToString(MonthConstants.DECEMBER); 213         assertEquals("December", test); 215     } 217     /** 218      * 1900 is not a leap year. 219      */ 220     public void testIsNotLeapYear1900() { 221         assertTrue(!SerialDate.isLeapYear(1900)); 222     } 224     /** 225      * 2000 is a leap year. 226      */ 227     public void testIsLeapYear2000() { 228         assertTrue(SerialDate.isLeapYear(2000)); 229     } 231     /** 232      * The number of leap years from 1900 up-to-and-including 1899 is 0. 233      */ 234     public void testLeapYearCount1899() { 235         assertEquals(SerialDate.leapYearCount(1899), 0); 236     } 238     /** 239      * The number of leap years from 1900 up-to-and-including 1903 is 0. 240      */ 241     public void testLeapYearCount1903() { 242         assertEquals(SerialDate.leapYearCount(1903), 0); 243     } 245     /** 246      * The number of leap years from 1900 up-to-and-including 1904 is 1. 247      */ Listing B-2 (continued)</p>\n<h3>SerialDateTest.java</h3>\n<p>370Appendix B: org.jfree.date.SerialDate 248     public void testLeapYearCount1904() { 249         assertEquals(SerialDate.leapYearCount(1904), 1); 250     } 252     /** 253      * The number of leap years from 1900 up-to-and-including 1999 is 24. 254      */ 255     public void testLeapYearCount1999() { 256         assertEquals(SerialDate.leapYearCount(1999), 24); 257     } 259     /** 260      * The number of leap years from 1900 up-to-and-including 2000 is 25. 261      */ 262     public void testLeapYearCount2000() { 263         assertEquals(SerialDate.leapYearCount(2000), 25); 264     } 266     /** 267      * Serialize an instance, restore it, and check for equality. 268      */ 269     public void testSerialization() {</p>\n<h3>271         SerialDate d1 = SerialDate.createInstance(15, 4, 2000);</h3>\n<h3>272         SerialDate d2 = null;</h3>\n<p>274         try {</p>\n<h3>275             ByteArrayOutputStream buffer = new ByteArrayOutputStream();</h3>\n<h3>276             ObjectOutput out = new ObjectOutputStream(buffer);</h3>\n<p>277             out.writeObject(d1); 278             out.close();</p>\n<h3>280             ObjectInput in = new ObjectInputStream(</h3>\n<p>new ByteArrayInputStream(buffer.toByteArray())); 281             d2 = (SerialDate) in.readObject(); 282             in.close(); 283         } 284         catch (Exception e) {</p>\n<h3>285             System.out.println(e.toString());</h3>\n<p>286         } 287         assertEquals(d1, d2); 289     } 291     /** 292      * A test for bug report 1096282 (now fixed). 293      */ 294     public void test1096282() {</p>\n<h3>295         SerialDate d = SerialDate.createInstance(29, 2, 2004);</h3>\n<p>296         d = SerialDate.addYears(1, d);</p>\n<h3>297         SerialDate expected = SerialDate.createInstance(28, 2, 2005);</h3>\n<p>298         assertTrue(d.isOn(expected)); 299     } 301     /** 302      * Miscellaneous tests for the addMonths() method. 303      */ 304     public void testAddMonths() {</p>\n<h3>305         SerialDate d1 = SerialDate.createInstance(31, 5, 2004);</h3>\n<p>Listing B-2 (continued)</p>\n<h3>SerialDateTest.java</h3>\n<p>371Appendix B: org.jfree.date.SerialDate</p>\n<h3>307         SerialDate d2 = SerialDate.addMonths(1, d1);</h3>\n<p>308         assertEquals(30, d2.getDayOfMonth()); 309         assertEquals(6, d2.getMonth()); 310         assertEquals(2004, d2.getYYYY());</p>\n<h3>312         SerialDate d3 = SerialDate.addMonths(2, d1);</h3>\n<p>313         assertEquals(31, d3.getDayOfMonth()); 314         assertEquals(7, d3.getMonth()); 315         assertEquals(2004, d3.getYYYY()); 317         SerialDate d4 = SerialDate.addMonths(1, SerialDate.addMonths(1, d1)); 318         assertEquals(30, d4.getDayOfMonth()); 319         assertEquals(7, d4.getMonth()); 320         assertEquals(2004, d4.getYYYY()); 321     } 322 } Listing B-2 (continued)</p>\n<h3>SerialDateTest.java</h3>\n<p>372Appendix B: org.jfree.date.SerialDate Listing B-3 MonthConstants.java 1 /* ======================================================================== 2  * JCommon : a free general purpose class library for the Java(tm) platform 3  * ======================================================================== 4  * 5  * (C) Copyright 2000-2005, by Object Refinery Limited and Contributors. 6  * 7  * Project Info:  http://www.jfree.org/jcommon/index.html 8  * 9  * This library i