 64     /** Constant for April. */ 65     public static final int APRIL = 4; 67     /** Constant for May. */ 68     public static final int MAY = 5; 70     /** Constant for June. */ 71     public static final int JUNE = 6; 73     /** Constant for July. */ 74     public static final int JULY = 7; 76     /** Constant for August. */ 77     public static final int AUGUST = 8; 79     /** Constant for September. */ 80     public static final int SEPTEMBER = 9; 82     /** Constant for October. */ 83     public static final int OCTOBER = 10; 85     /** Constant for November. */ 86     public static final int NOVEMBER = 11; 88     /** Constant for December. */ 89     public static final int DECEMBER = 12; 91 } Listing B-3 (continued)</p>\n<h3>MonthConstants.java</h3>\n<p>374Appendix B: org.jfree.date.SerialDate Listing B-4 BobsSerialDateTest.java 1 package org.jfree.date.junit; 3 import junit.framework.TestCase; 4 import org.jfree.date.*; 5 import static org.jfree.date.SerialDate.*; 7 import java.util.*; 9 public class BobsSerialDateTest extends TestCase { 11   public void testIsValidWeekdayCode() throws Exception { 12     for (int day = 1; day <= 7; day++) 13       assertTrue(isValidWeekdayCode(day)); 14     assertFalse(isValidWeekdayCode(0)); 15     assertFalse(isValidWeekdayCode(8)); 16   } 18   public void testStringToWeekdayCode() throws Exception { 20     assertEquals(-1, stringToWeekdayCode("Hello")); 21     assertEquals(MONDAY, stringToWeekdayCode("Monday")); 22     assertEquals(MONDAY, stringToWeekdayCode("Mon")); 23 //todo    assertEquals(MONDAY,stringToWeekdayCode("monday")); 24 //    assertEquals(MONDAY,stringToWeekdayCode("MONDAY")); 25 //    assertEquals(MONDAY, stringToWeekdayCode("mon")); 27     assertEquals(TUESDAY, stringToWeekdayCode("Tuesday")); 28     assertEquals(TUESDAY, stringToWeekdayCode("Tue")); 29 //    assertEquals(TUESDAY,stringToWeekdayCode("tuesday")); 30 //    assertEquals(TUESDAY,stringToWeekdayCode("TUESDAY")); 31 //    assertEquals(TUESDAY