COPY public.youtube_transcripts (video_id, target_lang, title, subtitles, created_at) FROM stdin;
5MuIMqhT8DM	vi	YouTube Video (5MuIMqhT8DM)	[{"text": "Translator: Mohamed Al-Dose. Proofreader: Riyad Altayeb.", "start": 0, "duration": 7, "translation": "Người dịch: Mohamed Al-Dose. Người hiệu đính: Riyad Altayeb."}, {"text": "Thank you very much.", "start": 0, "duration": 2.329, "translation": "Cảm ơn các bạn rất nhiều."}, {"text": "I'd like to begin by talking about testicles.", "start": 2.371, "duration": 4, "translation": "Tôi muốn bắt đầu bằng cách nói về tinh hoàn."}, {"text": "(Laughter)", "start": 6.663, "duration": 1.625, "translation": "(Tiếng cười)"}, {"text": "Men who sleep five hours a night", "start": 9.204, "duration": 2.75, "translation": "Những người đàn ông ngủ năm giờ mỗi đêm"}, {"text": "have significantly smaller testicles compared to those who sleep seven hours or more.", "start": 11.954, "duration": 5.25, "translation": "có tinh hoàn nhỏ hơn đáng kể so với những người ngủ bảy giờ trở lên."}, {"text": "(Laughter)", "start": 17.246, "duration": 2.792, "translation": "(Tiếng cười)"}, {"text": "In addition, men who usually sleep only between four and five hours a night", "start": 20.079, "duration": 5.084, "translation": "Ngoài ra, những người đàn ông thường chỉ ngủ từ bốn đến năm giờ mỗi đêm"}, {"text": "will have a testosterone level", "start": 25.163, "duration": 2.541, "translation": "sẽ có mức testosterone"}, {"text": "equivalent to someone ten years older than them.", "start": 27.704, "duration": 3.334, "translation": "tương đương với một người lớn hơn họ mười tuổi."}, {"text": "So, a lack of sleep will age a man by ten years", "start": 33.079, "duration": 3.75, "translation": "Vì vậy, thiếu ngủ sẽ làm một người đàn ông già đi mười tuổi"}, {"text": "in terms of that fundamental aspect of health.", "start": 36.871, "duration": 2.791, "translation": "về khía cạnh sức khỏe cơ bản đó."}, {"text": "We also observe a similar dysfunction in female reproductive health", "start": 41.954, "duration": 4.417, "translation": "Chúng ta cũng quan sát thấy một rối loạn chức năng tương tự trong sức khỏe sinh sản của phụ nữ"}, {"text": "due to lack of sleep.", "start": 46.371, "duration": 1.416, "translation": "do thiếu ngủ."}, {"text": "This is the best news I have for you today.", "start": 51.079, "duration": 2.667, "translation": "Đây là tin tốt nhất tôi có cho các bạn hôm nay."}, {"text": "(Laughter)", "start": 53.746, "duration": 2.666, "translation": "(Tiếng cười)"}, {"text": "From this moment on, things might get worse.", "start": 56.454, "duration": 2.375, "translation": "Từ giờ trở đi, mọi thứ có thể trở nên tồi tệ hơn."}, {"text": "I won't just tell you about the wonderful good things", "start": 58.871, "duration": 2.75, "translation": "Tôi sẽ không chỉ kể cho các bạn nghe về những điều tốt đẹp tuyệt vời"}, {"text": "that happen when you sleep,", "start": 61.662, "duration": 1.834, "translation": "xảy ra khi bạn ngủ,"}, {"text": "but also about the disturbing bad things that happen when you don't get enough sleep.", "start": 63.537, "duration": 4.459, "translation": "mà còn về những điều tồi tệ đáng lo ngại xảy ra khi bạn không ngủ đủ giấc."}, {"text": "For both your body and your brain.", "start": 68.038, "duration": 2.5, "translation": "Cho cả cơ thể và bộ não của bạn."}, {"text": "Let me start with the brain.", "start": 71.371, "duration": 2.417, "translation": "Hãy để tôi bắt đầu với bộ não."}, {"text": "and its learning and memory functions.", "start": 73.829, "duration": 3, "translation": "và các chức năng học tập và ghi nhớ của nó."}, {"text": "because what we've discovered in the last ten years or so", "start": 76.871, "duration": 3.25, "translation": "bởi vì những gì chúng ta đã khám phá trong khoảng mười năm qua"}, {"text": "is that you need to sleep after learning", "start": 80.163, "duration": 2.875, "translation": "là bạn cần ngủ sau khi học"}, {"text": "to press the \\"save\\" button for these new memories,", "start": 83.079, "duration": 3.292, "translation": "để nhấn nút \\"lưu\\" cho những ký ức mới này,"}, {"text": "so you don't forget them.", "start": 86.371, "duration": 1.292, "translation": "để bạn không quên chúng."}, {"text": "But we've recently discovered that you also need to sleep before learning", "start": 88.954, "duration": 5.5, "translation": "Nhưng gần đây chúng tôi đã phát hiện ra rằng bạn cũng cần ngủ trước khi học"}, {"text": "to prepare your brain,", "start": 94.496, "duration": 3.042, "translation": "để chuẩn bị cho bộ não của bạn,"}, {"text": "almost like a dry sponge,", "start": 97.579, "duration": 2.042, "translation": "gần giống như một miếng bọt biển khô,"}, {"text": "initially ready to absorb new information.", "start": 99.663, "duration": 2.458, "translation": "ban đầu đã sẵn sàng để hấp thụ thông tin mới."}, {"text": "And without sleep, the memory pathways in the brain", "start": 103.163, "duration": 3.125, "translation": "Và nếu không ngủ, các đường dẫn bộ nhớ trong não"}, {"text": "become waterlogged, so to speak,", "start": 106.288, "duration": 2.791, "translation": "sẽ trở nên úng nước, nói cách khác,"}, {"text": "and won't be able to absorb new information.", "start": 109.079, "duration": 2.167, "translation": "và sẽ không thể hấp thụ thông tin mới."}, {"text": "So, let me show you the data.", "start": 112.163, "duration": 1.916, "translation": "Vậy, hãy để tôi cho bạn xem dữ liệu."}, {"text": "Here in this study, we decided to examine the hypothesis", "start": 114.079, "duration": 4.25, "translation": "Trong nghiên cứu này, chúng tôi quyết định kiểm tra giả thuyết"}, {"text": "that staying up all night is a good idea.", "start": 118.371, "duration": 2.542, "translation": "rằng thức trắng đêm là một ý hay."}, {"text": "So, we took a group of individuals", "start": 122.246, "duration": 2.333, "translation": "Vì vậy, chúng tôi đã lấy một nhóm cá nhân"}, {"text": "and sorted them into one of two experimental groups:", "start": 124.621, "duration": 3.542, "translation": "và phân loại họ vào một trong hai nhóm thử nghiệm:"}, {"text": "the sleep group and the sleep deprivation group.", "start": 128.204, "duration": 3.459, "translation": "nhóm ngủ và nhóm thiếu ngủ."}, {"text": "The sleep group will get eight full hours of sleep,", "start": 131.663, "duration": 4.625, "translation": "Nhóm ngủ sẽ được ngủ đủ tám tiếng,"}, {"text": "but we will keep the sleep deprivation group awake", "start": 136.329, "duration": 2.667, "translation": "nhưng chúng tôi sẽ giữ nhóm thiếu ngủ thức"}, {"text": "in the lab, under full supervision.", "start": 138.996, "duration": 2.167, "translation": "trong phòng thí nghiệm, dưới sự giám sát hoàn toàn."}, {"text": "No naps or caffeine, by the way, so it's miserable for all participants.", "start": 141.663, "duration": 4.375, "translation": "Nhân tiện, không có giấc ngủ ngắn hay caffeine, nên mọi người tham gia đều khổ sở."}, {"text": "And the next day,", "start": 146.579, "duration": 1.542, "translation": "Và ngày hôm sau,"}, {"text": "we will put these participants inside an MRI scanner", "start": 148.121, "duration": 4.333, "translation": "chúng tôi sẽ đưa những người tham gia này vào máy chụp cộng hưởng từ"}, {"text": "and have them try to learn a whole list of new information", "start": 152.454, "duration": 3.792, "translation": "và yêu cầu họ cố gắng học một danh sách đầy đủ thông tin mới"}, {"text": "while we take photographic snapshots of brain activity.", "start": 156.288, "duration": 3.291, "translation": "trong khi chúng tôi chụp ảnh nhanh hoạt động của não."}, {"text": "And then we will test them", "start": 159.579, "duration": 2, "translation": "Và sau đó chúng tôi sẽ kiểm tra họ"}, {"text": "to see how effective that learning was.", "start": 161.579, "duration": 2.5, "translation": "để xem việc học đó hiệu quả đến mức nào."}, {"text": "And this is what you're looking at here on the vertical axis.", "start": 164.954, "duration": 2.917, "translation": "Và đây là những gì bạn đang nhìn thấy ở đây trên trục tung."}, {"text": "And when you put these two groups head-to-head,", "start": 168.496, "duration": 2.708, "translation": "Và khi bạn đặt hai nhóm này đối đầu,"}, {"text": "what you see is a clear 40% deficit", "start": 171.204, "duration": 5.042, "translation": "điều bạn thấy là một sự thiếu hụt rõ ràng 40%"}, {"text": "in the brain's ability to make new memories without sleep.", "start": 176.288, "duration": 3.458, "translation": "trong khả năng tạo ra ký ức mới của não mà không có giấc ngủ."}, {"text": "I think this should be concerning,", "start": 181.038, "duration": 1.833, "translation": "Tôi nghĩ điều này đáng lo ngại,"}, {"text": "considering what's happening to sleep", "start": 182.913, "duration": 2.208, "translation": "khi xem xét những gì đang xảy ra với giấc ngủ"}, {"text": "in educational programs currently.", "start": 185.163, "duration": 2.416, "translation": "trong các chương trình giáo dục hiện nay."}, {"text": "In fact, if we project that onto reality,", "start": 188.538, "duration": 1.833, "translation": "Thực tế, nếu chúng ta áp dụng điều đó vào thực tế,"}, {"text": "it would be like the difference between a child excelling in a test", "start": 190.371, "duration": 3.5, "translation": "nó sẽ giống như sự khác biệt giữa một đứa trẻ xuất sắc trong một bài kiểm tra"}, {"text": "and another miserably failing it... 40%.", "start": 193.913, "duration": 2.875, "translation": "và một đứa khác trượt thảm hại... 40%."}, {"text": "And we continued to discover what goes wrong inside your brain.", "start": 198.288, "duration": 4.208, "translation": "Và chúng tôi tiếp tục khám phá điều gì đang xảy ra sai lệch bên trong não của bạn."}, {"text": "Which then results in these types of learning difficulties.", "start": 202.496, "duration": 3.167, "translation": "Điều này sau đó dẫn đến những loại khó khăn trong học tập này."}, {"text": "There's a structure that exists", "start": 206.746, "duration": 1.583, "translation": "Có một cấu trúc tồn tại"}, {"text": "on both the right and left sides of the brain, called the hippocampus.", "start": 208.371, "duration": 4.625, "translation": "ở cả bên phải và bên trái của não, được gọi là hồi hải mã."}, {"text": "And you can imagine the hippocampus", "start": 212.996, "duration": 1.792, "translation": "Và bạn có thể hình dung hồi hải mã"}, {"text": "almost like your brain's information inbox.", "start": 214.829, "duration": 3.209, "translation": "gần giống như hộp thư đến thông tin của não bạn."}, {"text": "It's very good at receiving new memory files.", "start": 218.621, "duration": 3.208, "translation": "Nó rất giỏi trong việc tiếp nhận các tệp bộ nhớ mới."}, {"text": "And then retaining them.", "start": 221.829, "duration": 1.5, "translation": "Và sau đó giữ lại chúng."}, {"text": "And when you look at this structure", "start": 224.913, "duration": 1.708, "translation": "Và khi bạn nhìn vào cấu trúc này,"}, {"text": "in those people who get full hours of sleep,", "start": 226.663, "duration": 3.041, "translation": "ở những người có đủ số giờ ngủ,"}, {"text": "you'll see a lot of healthy, learning-related activity.", "start": 229.746, "duration": 3.542, "translation": "bạn sẽ thấy rất nhiều hoạt động lành mạnh liên quan đến học tập."}, {"text": "But in those people who were deprived of sleep,", "start": 234.621, "duration": 2.958, "translation": "Nhưng ở những người bị thiếu ngủ,"}, {"text": "we actually couldn't find any significant signal at all.", "start": 237.621, "duration": 3.625, "translation": "chúng tôi thực sự không thể tìm thấy bất kỳ tín hiệu đáng kể nào cả."}, {"text": "So it seems as if sleep deprivation has essentially shut down your information inbox,", "start": 242.746, "duration": 4.958, "translation": "Vì vậy, có vẻ như việc thiếu ngủ đã cơ bản đóng hộp thư đến thông tin của bạn,"}, {"text": "and any new incoming files will simply be bounced away.", "start": 247.746, "duration": 2.958, "translation": "và bất kỳ tệp mới nào đến sẽ đơn giản bị trả lại."}, {"text": "You can no longer effectively input new experiences into your memory.", "start": 251.913, "duration": 3.583, "translation": "Bạn không còn có thể nhập hiệu quả những trải nghiệm mới vào bộ nhớ của mình."}, {"text": "This is the damage that can happen if I deprive you of sleep,", "start": 258.038, "duration": 4.5, "translation": "Đây là thiệt hại có thể xảy ra nếu tôi tước đi giấc ngủ của bạn,"}, {"text": "But let me just go back to that control group for a second.", "start": 262.579, "duration": 3.084, "translation": "Nhưng hãy để tôi quay lại nhóm đối chứng đó một giây."}, {"text": "Do you remember those people who got a full eight hours of sleep?", "start": 266.454, "duration": 3.334, "translation": "Bạn có nhớ những người đã ngủ đủ tám tiếng không?"}, {"text": "We can ask a completely different question:", "start": 270.413, "duration": 2.458, "translation": "Chúng ta có thể đặt một câu hỏi hoàn toàn khác:"}, {"text": "What about the physiological quality of your sleep,", "start": 272.913, "duration": 3.625, "translation": "Còn chất lượng sinh lý giấc ngủ của bạn thì sao,"}, {"text": "when you get it,", "start": 276.538, "duration": 1.541, "translation": "khi bạn có được nó,"}, {"text": "which restores and enhances your memory and ability to learn", "start": 278.121, "duration": 3.792, "translation": "giúp phục hồi và tăng cường trí nhớ cũng như khả năng học hỏi của bạn"}, {"text": "every day?", "start": 281.954, "duration": 1.125, "translation": "mỗi ngày?"}, {"text": "And by placing electrodes all over the head,", "start": 283.996, "duration": 3, "translation": "Và bằng cách đặt các điện cực khắp đầu,"}, {"text": "what we discovered is that there are large and powerful brainwaves", "start": 286.996, "duration": 4.042, "translation": "điều chúng tôi phát hiện ra là có những sóng não lớn và mạnh mẽ"}, {"text": "that occur during the deepest stages of sleep,", "start": 291.079, "duration": 3.625, "translation": "xảy ra trong các giai đoạn sâu nhất của giấc ngủ,"}, {"text": "upon which something rides:", "start": 294.704, "duration": 2.292, "translation": "mà trên đó có thứ gì đó đang cưỡi lên:"}, {"text": "these amazing pulses of electrical activity,", "start": 297.038, "duration": 3.25, "translation": "những xung điện hoạt động đáng kinh ngạc này,"}, {"text": "which we call sleep spindles.", "start": 300.329, "duration": 1.75, "translation": "mà chúng tôi gọi là thoi ngủ."}, {"text": "It is the integrated quality of deep sleep brainwaves", "start": 303.079, "duration": 4.417, "translation": "Đó là chất lượng tích hợp của sóng não giấc ngủ sâu"}, {"text": "that acts like a file transfer mechanism at night,", "start": 307.496, "duration": 4.458, "translation": "hoạt động như một cơ chế truyền tệp vào ban đêm,"}, {"text": "transferring information from a fragile, short-term reservoir", "start": 311.996, "duration": 4.083, "translation": "chuyển thông tin từ một kho chứa dễ hỏng, ngắn hạn"}, {"text": "to a permanent, long-term storage site within the brain,", "start": 316.079, "duration": 4.334, "translation": "đến một vị trí lưu trữ vĩnh viễn, dài hạn bên trong não,"}, {"text": "thereby protecting and securing this information.", "start": 320.454, "duration": 3.375, "translation": "từ đó bảo vệ và giữ an toàn cho thông tin này."}, {"text": "And it's important to understand", "start": 325.454, "duration": 2.042, "translation": "Và điều quan trọng là phải hiểu"}, {"text": "what provides these benefits for memory,", "start": 327.538, "duration": 5.041, "translation": "điều gì mang lại những lợi ích này cho trí nhớ,"}, {"text": "because there are real medical and social consequences.", "start": 332.621, "duration": 4.125, "translation": "bởi vì có những hậu quả y tế và xã hội thực sự."}, {"text": "And let me just tell you about one area", "start": 336.788, "duration": 2, "translation": "Và hãy để tôi kể cho bạn nghe về một lĩnh vực"}, {"text": "to which we have clinically transferred our work.", "start": 338.788, "duration": 3.458, "translation": "mà chúng tôi đã chuyển công việc của mình sang đó một cách lâm sàng."}, {"text": "This is the field of aging and dementia.", "start": 342.288, "duration": 3.208, "translation": "Đây là lĩnh vực lão hóa và sa sút trí tuệ."}, {"text": "Because, of course, it's no secret that as we get older,", "start": 346.913, "duration": 3.166, "translation": "Bởi vì, tất nhiên, không có gì bí mật khi chúng ta càng lớn tuổi,"}, {"text": "our abilities to learn and our memory start to fade and decline.", "start": 350.288, "duration": 3.125, "translation": "khả năng học hỏi và trí nhớ của chúng ta bắt đầu phai nhạt và suy giảm."}, {"text": "But we've also discovered", "start": 354.996, "duration": 1.792, "translation": "Nhưng chúng tôi cũng đã khám phá ra"}, {"text": "that one of the physiological hallmarks of aging is that sleep gets worse,", "start": 356.829, "duration": 6.459, "translation": "rằng một trong những dấu hiệu sinh lý của lão hóa là giấc ngủ trở nên tệ hơn,"}, {"text": "especially the type of deep sleep I was just discussing.", "start": 363.621, "duration": 4.125, "translation": "đặc biệt là loại giấc ngủ sâu mà tôi vừa thảo luận."}, {"text": "And last year, we finally published evidence", "start": 368.538, "duration": 3.125, "translation": "Và năm ngoái, chúng tôi cuối cùng đã công bố bằng chứng"}, {"text": "that these two things are not simply correlated,", "start": 371.663, "duration": 2.916, "translation": "rằng hai điều này không chỉ đơn thuần là tương quan,"}, {"text": "but are profoundly interconnected.", "start": 374.829, "duration": 3.292, "translation": "mà chúng có mối liên hệ sâu sắc với nhau."}, {"text": "This evidence suggests that the absence of deep sleep", "start": 378.871, "duration": 3.458, "translation": "Bằng chứng này cho thấy rằng việc thiếu ngủ sâu"}, {"text": "is an underappreciated factor", "start": 382.371, "duration": 2, "translation": "là một yếu tố bị đánh giá thấp"}, {"text": "contributing to cognitive decline or memory deterioration,", "start": 384.413, "duration": 3.583, "translation": "góp phần vào sự suy giảm nhận thức hoặc suy giảm trí nhớ,"}, {"text": "and in aging, and more recently,", "start": 387.996, "duration": 3.75, "translation": "và trong quá trình lão hóa, và gần đây hơn,"}, {"text": "in Alzheimer's disease as well.", "start": 391.954, "duration": 4.125, "translation": "cả trong bệnh Alzheimer nữa."}, {"text": "I know this news is incredibly disheartening.", "start": 396.079, "duration": 3.292, "translation": "Tôi biết tin tức này vô cùng đáng thất vọng."}, {"text": "You will inevitably go through it. It's coming for you.", "start": 399.704, "duration": 2.042, "translation": "Bạn chắc chắn sẽ trải qua điều đó. Nó đang đến với bạn."}, {"text": "But there is a silver lining here.", "start": 401.746, "duration": 4.208, "translation": "Nhưng có một khía cạnh tích cực ở đây."}, {"text": "Unlike many factors associated with aging,", "start": 405.954, "duration": 4.334, "translation": "Không giống như nhiều yếu tố liên quan đến lão hóa,"}, {"text": "such as changes in the brain's physical structure,", "start": 410.329, "duration": 3.709, "translation": "chẳng hạn như những thay đổi trong cấu trúc vật lý của não,"}, {"text": "treating that is incredibly difficult.", "start": 414.038, "duration": 3.333, "translation": "việc điều trị điều đó vô cùng khó khăn."}, {"text": "But the fact that sleep is a missing piece in the explanatory puzzle", "start": 417.413, "duration": 4.166, "translation": "Nhưng việc giấc ngủ là một mảnh ghép còn thiếu trong bức tranh giải thích"}, {"text": "of aging and Alzheimer's disease is exciting.", "start": 421.621, "duration": 2.708, "translation": "về lão hóa và bệnh Alzheimer là điều thú vị."}, {"text": "Because perhaps we can do something about it.", "start": 424.538, "duration": 4.041, "translation": "Bởi vì có lẽ chúng ta có thể làm gì đó với nó."}, {"text": "And one of the ways we're tackling this at my sleep center,", "start": 428.579, "duration": 3.917, "translation": "Và một trong những cách chúng tôi đang giải quyết vấn đề này tại trung tâm giấc ngủ của tôi,"}, {"text": "is not by using sleeping pills, by the way,", "start": 432.496, "duration": 2.917, "translation": "không phải bằng cách dùng thuốc ngủ đâu nhé,"}, {"text": "which are unfortunately useless tools that don't lead to deep sleep.", "start": 435.621, "duration": 5.083, "translation": "mà thật không may, chúng là những công cụ vô dụng không dẫn đến giấc ngủ sâu."}, {"text": "Instead, we're developing a new method based on the following:", "start": 441.329, "duration": 3.667, "translation": "Thay vào đó, chúng tôi đang phát triển một phương pháp mới dựa trên điều sau:"}, {"text": "It's called transcranial direct current electrical brain stimulation.", "start": 445.038, "duration": 3.291, "translation": "Nó được gọi là kích thích điện não dòng điện một chiều xuyên sọ."}, {"text": "A small amount of electrical voltage is delivered into the brain,", "start": 448.329, "duration": 2.25, "translation": "Một lượng nhỏ điện áp được đưa vào não,"}, {"text": "so small that you typically don't feel it,", "start": 451.538, "duration": 1.916, "translation": "nhỏ đến mức bạn thường không cảm thấy gì,"}, {"text": "but it has a remarkable effect.", "start": 453.829, "duration": 3.042, "translation": "nhưng nó có một tác dụng đáng kể."}, {"text": "If you apply this stimulation during sleep in healthy adults,", "start": 456.996, "duration": 6.125, "translation": "Nếu bạn áp dụng kích thích này trong khi ngủ ở người lớn khỏe mạnh,"}, {"text": "as if you're singing in time with those deep sleep brain waves,", "start": 463.329, "duration": 4.667, "translation": "như thể bạn đang hát đúng nhịp với những sóng não ngủ sâu đó,"}, {"text": "not only can you amplify the size of those deep sleep brain waves,", "start": 467.996, "duration": 4.042, "translation": "bạn không chỉ có thể khuếch đại kích thước của những sóng não ngủ sâu đó,"}, {"text": "but by doing so, we can almost double the amount of memory benefit", "start": 472.329, "duration": 4.875, "translation": "mà bằng cách đó, chúng ta có thể gần như tăng gấp đôi lợi ích về trí nhớ"}, {"text": "that you get from sleep.", "start": 477.246, "duration": 1.75, "translation": "mà bạn nhận được từ giấc ngủ."}, {"text": "And the question now is whether we can translate", "start": 479.163, "duration": 3.25, "translation": "Và câu hỏi bây giờ là liệu chúng ta có thể chuyển giao"}, {"text": "the same cheap and portable technology", "start": 482.413, "duration": 4.083, "translation": "cùng một công nghệ rẻ tiền và di động này"}, {"text": "to older adults and those with mental illnesses.", "start": 486.496, "duration": 3, "translation": "cho người lớn tuổi và những người mắc bệnh tâm thần hay không."}, {"text": "Can we restore some of that healthy deep sleep quality,", "start": 490.746, "duration": 4.708, "translation": "Liệu chúng ta có thể khôi phục lại một phần chất lượng giấc ngủ sâu khỏe mạnh đó,"}, {"text": "And in doing so, can we save aspects of learning?", "start": 495.496, "duration": 4.583, "translation": "Và khi làm như vậy, liệu chúng ta có thể cứu vãn các khía cạnh của việc học không?"}, {"text": "And memory functions?", "start": 500.079, "duration": 1.709, "translation": "Và các chức năng của trí nhớ?"}, {"text": "This is my real hope right now.", "start": 501.829, "duration": 2.042, "translation": "Đây là hy vọng thực sự của tôi lúc này."}, {"text": "This is one of our ambitious goals.", "start": 504.454, "duration": 4.25, "translation": "Đây là một trong những mục tiêu đầy tham vọng của chúng tôi."}, {"text": "This is an example of sleep's effect on your brain,", "start": 509.413, "duration": 3.333, "translation": "Đây là một ví dụ về tác động của giấc ngủ lên não bộ của bạn,"}, {"text": "but sleep is also important for your body.", "start": 512.746, "duration": 2.958, "translation": "nhưng giấc ngủ cũng quan trọng đối với cơ thể bạn."}, {"text": "We previously talked about sleep deprivation and the reproductive system,", "start": 517.246, "duration": 3.791, "translation": "Trước đây chúng ta đã nói về việc thiếu ngủ và hệ sinh sản,"}, {"text": "or I can tell you about sleep deprivation and the cardiovascular system,", "start": 521.787, "duration": 4.334, "translation": "hoặc tôi có thể nói với bạn về việc thiếu ngủ và hệ tim mạch,"}, {"text": "and the deficiency is just one hour of sleep.", "start": 526.704, "duration": 3.417, "translation": "và sự thiếu hụt chỉ là một giờ ngủ."}, {"text": "Because there's a global experiment conducted on 1.6 billion people", "start": 530.204, "duration": 4.917, "translation": "Bởi vì có một thí nghiệm toàn cầu được thực hiện trên 1,6 tỷ người"}, {"text": "in 70 countries, twice a year,", "start": 535.204, "duration": 3.458, "translation": "ở 70 quốc gia, hai lần một năm,"}, {"text": "and it's called Daylight Saving Time.", "start": 539.496, "duration": 2.541, "translation": "và nó được gọi là Giờ tiết kiệm ánh sáng ban ngày."}, {"text": "In the spring, when we lose an hour of sleep,", "start": 542.996, "duration": 3.75, "translation": "Vào mùa xuân, khi chúng ta mất một giờ ngủ,"}, {"text": "we see a 24% increase in heart attacks the very next day.", "start": 546.746, "duration": 6.416, "translation": "chúng ta thấy số ca đau tim tăng 24% vào ngày hôm sau."}, {"text": "In the fall, when we gain an hour of sleep,", "start": 554.996, "duration": 3.541, "translation": "Vào mùa thu, khi chúng ta có thêm một giờ ngủ,"}, {"text": "we see a 21% decrease in heart attacks.", "start": 558.662, "duration": 2.917, "translation": "chúng ta thấy số ca đau tim giảm 21%."}, {"text": "Isn't that amazing?", "start": 563.996, "duration": 3.125, "translation": "Điều đó không đáng kinh ngạc sao?"}, {"text": "And you see the same thing for car accidents and road accidents,", "start": 567.121, "duration": 4.791, "translation": "Và bạn cũng thấy điều tương tự đối với tai nạn ô tô và tai nạn giao thông,"}, {"text": "and even suicide rates.", "start": 571.954, "duration": 2.917, "translation": "và thậm chí cả tỷ lệ tự tử."}, {"text": "But to dive deeper into the topic, I want to focus on:", "start": 576.954, "duration": 2.458, "translation": "Nhưng để đi sâu hơn vào chủ đề này, tôi muốn tập trung vào:"}, {"text": "Sleep deprivation and the immune system.", "start": 579.496, "duration": 3.541, "translation": "Thiếu ngủ và hệ miễn dịch."}, {"text": "And here, I'll show you these beautiful blue things in the picture.", "start": 583.079, "duration": 4.792, "translation": "Và ở đây, tôi sẽ cho các bạn thấy những thứ màu xanh đẹp đẽ này trong hình."}, {"text": "They are called natural killer cells,", "start": 587.912, "duration": 3.209, "translation": "Chúng được gọi là tế bào tiêu diệt tự nhiên,"}, {"text": "And you can imagine natural killer cells almost like Secret Service agents", "start": 591.121, "duration": 5.125, "translation": "Và bạn có thể hình dung các tế bào tiêu diệt tự nhiên gần giống như các đặc vụ Mật vụ"}, {"text": "for your immune system.", "start": 596.246, "duration": 1.5, "translation": "của hệ miễn dịch của bạn."}, {"text": "They are very good at identifying dangerous and unwanted elements,", "start": 597.787, "duration": 4.667, "translation": "Chúng rất giỏi trong việc xác định các yếu tố nguy hiểm và không mong muốn,"}, {"text": "and eliminating them.", "start": 602.662, "duration": 1.584, "translation": "và loại bỏ chúng."}, {"text": "In fact, what it's doing here is destroying a cancerous tumor.", "start": 605.371, "duration": 5.333, "translation": "Trên thực tế, điều mà nó đang làm ở đây là tiêu diệt một khối u ung thư."}, {"text": "So, what you hope for is to have a strong army of these killers", "start": 610.704, "duration": 6, "translation": "Vì vậy, điều bạn hy vọng là có một đội quân mạnh mẽ gồm những kẻ tiêu diệt này"}, {"text": "at all times,", "start": 616.704, "duration": 1.958, "translation": "mọi lúc,"}, {"text": "and that's what you don't get when you don't get enough sleep.", "start": 618.704, "duration": 3.708, "translation": "và đó là điều bạn không có được khi bạn không ngủ đủ giấc."}, {"text": "And so, in this experiment,", "start": 624.246, "duration": 1.625, "translation": "Và vì vậy, trong thí nghiệm này,"}, {"text": "you won't be deprived of sleep for a full night,", "start": 625.871, "duration": 3.583, "translation": "bạn sẽ không bị thiếu ngủ cả đêm,"}, {"text": "but your sleep hours will simply be reduced to four hours", "start": 629.579, "duration": 3.75, "translation": "mà thời gian ngủ của bạn sẽ chỉ đơn giản là giảm xuống còn bốn giờ"}, {"text": "for one night,", "start": 633.371, "duration": 1.583, "translation": "trong một đêm,"}, {"text": "and then we'll see the percentage decrease", "start": 634.954, "duration": 2.792, "translation": "và sau đó chúng ta sẽ thấy tỷ lệ giảm"}, {"text": "in the immune cell activity you experience.", "start": 637.829, "duration": 3.083, "translation": "trong hoạt động của tế bào miễn dịch mà bạn trải qua."}, {"text": "And this percentage isn't small... it's not 10%,", "start": 640.912, "duration": 2.75, "translation": "Và tỷ lệ này không nhỏ... không phải 10%,"}, {"text": "it's not 20%.", "start": 643.704, "duration": 2.292, "translation": "không phải 20%."}, {"text": "Instead, there was a 70% decrease in natural killer cell activity.", "start": 646.079, "duration": 4.833, "translation": "Thay vào đó, có sự sụt giảm 70% trong hoạt động của tế bào tiêu diệt tự nhiên."}, {"text": "This is a serious case of immune deficiency.", "start": 652.037, "duration": 5.417, "translation": "Đây là một trường hợp suy giảm miễn dịch nghiêm trọng."}, {"text": "And perhaps you can understand why we are now finding", "start": 657.454, "duration": 2.667, "translation": "Và có lẽ bạn có thể hiểu tại sao chúng ta hiện đang tìm thấy"}, {"text": "important links between short sleep duration", "start": 660.121, "duration": 3.916, "translation": "những mối liên hệ quan trọng giữa thời lượng ngủ ngắn"}, {"text": "and the risk of developing many forms of cancer.", "start": 664.121, "duration": 4.583, "translation": "và nguy cơ phát triển nhiều dạng ung thư."}, {"text": "Currently, the list includes bowel cancer,", "start": 669.787, "duration": 2.875, "translation": "Hiện tại, danh sách bao gồm ung thư ruột,"}, {"text": "prostate cancer, and breast cancer.", "start": 672.912, "duration": 4.875, "translation": "ung thư tuyến tiền liệt và ung thư vú."}, {"text": "In fact, the link between lack of sleep and cancer is very strong,", "start": 677.787, "duration": 4.959, "translation": "Trên thực tế, mối liên hệ giữa thiếu ngủ và ung thư là rất mạnh,"}, {"text": "to the extent that the World Health Organization", "start": 682.954, "duration": 2.917, "translation": "đến mức Tổ chức Y tế Thế giới"}, {"text": "has classified any night shift", "start": 685.912, "duration": 3.625, "translation": "đã phân loại bất kỳ ca làm đêm nào"}, {"text": "as a probable carcinogen,", "start": 689.787, "duration": 2.334, "translation": "là một chất gây ung thư tiềm năng,"}, {"text": "due to the disruption of sleep rhythms.", "start": 693.371, "duration": 3.25, "translation": "do sự gián đoạn của nhịp điệu giấc ngủ."}, {"text": "Perhaps you have heard that old saying,", "start": 697.704, "duration": 2.167, "translation": "Có lẽ bạn đã nghe câu nói cũ đó,"}, {"text": "that you can sleep when you die.", "start": 700.662, "duration": 1.625, "translation": "rằng bạn có thể ngủ khi bạn chết."}, {"text": "Well, I'm very serious now...", "start": 702.996, "duration": 1.791, "translation": "Chà, bây giờ tôi rất nghiêm túc..."}, {"text": "It's deadly and unwise advice.", "start": 705.079, "duration": 3.667, "translation": "Đó là một lời khuyên chết người và không khôn ngoan."}, {"text": "We know that from epidemiological studies involving millions of individuals.", "start": 708.746, "duration": 4.708, "translation": "Chúng ta biết điều đó từ các nghiên cứu dịch tễ học trên hàng triệu cá nhân."}, {"text": "There's a simple truth:", "start": 713.496, "duration": 1.916, "translation": "Có một sự thật đơn giản:"}, {"text": "The less you sleep, the shorter your life.", "start": 715.496, "duration": 3.541, "translation": "Bạn ngủ càng ít, tuổi thọ của bạn càng ngắn."}, {"text": "Lack of sleep predicts all causes of mortality.", "start": 719.079, "duration": 3.583, "translation": "Thiếu ngủ dự đoán tất cả các nguyên nhân gây tử vong."}, {"text": "And if the increased risk of developing cancer", "start": 724.954, "duration": 4.375, "translation": "Và nếu nguy cơ mắc ung thư tăng lên"}, {"text": "Or even developing Alzheimer's disease.", "start": 729.329, "duration": 2.333, "translation": "Hoặc thậm chí mắc bệnh Alzheimer."}, {"text": "worrying enough,", "start": 731.662, "duration": 3.709, "translation": "đủ đáng lo ngại,"}, {"text": "we discovered that a lack of sleep will reduce", "start": 735.496, "duration": 4.041, "translation": "chúng tôi phát hiện ra rằng thiếu ngủ sẽ làm giảm"}, {"text": "the very fabric of biological life itself,", "start": 739.662, "duration": 4.667, "translation": "chính cấu trúc sinh học của sự sống,"}, {"text": "the genetic code of DNA.", "start": 744.454, "duration": 4, "translation": "mã di truyền của DNA."}, {"text": "So, in this experiment, a group of healthy adults was taken,", "start": 748.537, "duration": 3.709, "translation": "Vì vậy, trong thí nghiệm này, một nhóm người trưởng thành khỏe mạnh đã được chọn,"}, {"text": "and their sleep hours were reduced to six hours a night", "start": 752.246, "duration": 3.25, "translation": "và thời gian ngủ của họ được giảm xuống còn sáu giờ mỗi đêm"}, {"text": "for one week.", "start": 755.537, "duration": 1.792, "translation": "trong một tuần."}, {"text": "Afterward, they measured the change in the gene activity profile", "start": 757.371, "duration": 4.166, "translation": "Sau đó, họ đo lường sự thay đổi trong hồ sơ hoạt động gen"}, {"text": "compared to when these same individuals were getting", "start": 761.537, "duration": 2, "translation": "so với khi những cá nhân này"}, {"text": "eight full hours of sleep at night.", "start": 763.537, "duration": 2.709, "translation": "ngủ đủ tám giờ mỗi đêm."}, {"text": "There were two important discoveries.", "start": 767.496, "duration": 2.416, "translation": "Có hai phát hiện quan trọng."}, {"text": "First, the activity of 711 significant genes was altered", "start": 770.287, "duration": 7.5, "translation": "Thứ nhất, hoạt động của 711 gen quan trọng đã bị thay đổi"}, {"text": "due to a lack of sleep.", "start": 777.829, "duration": 1.333, "translation": "do thiếu ngủ."}, {"text": "The second finding was that half of these genes", "start": 780.079, "duration": 3.042, "translation": "Phát hiện thứ hai là một nửa số gen này"}, {"text": "had increased activity.", "start": 783.121, "duration": 2.25, "translation": "có hoạt động tăng lên."}, {"text": "The other half had decreased activity.", "start": 785.371, "duration": 2.458, "translation": "Nửa còn lại có hoạt động giảm xuống."}, {"text": "These genes that were deactivated due to a lack of sleep", "start": 788.704, "duration": 2.625, "translation": "Những gen bị vô hiệu hóa do thiếu ngủ này"}, {"text": "were genes associated with the immune system.", "start": 791.371, "duration": 2.833, "translation": "là những gen liên quan đến hệ miễn dịch."}, {"text": "So, once again, you can observe immune deficiency.", "start": 795.454, "duration": 3.083, "translation": "Vì vậy, một lần nữa, bạn có thể nhận thấy sự suy giảm miễn dịch."}, {"text": "On the contrary, the genes that were upregulated", "start": 799.287, "duration": 3.084, "translation": "Ngược lại, các gen được điều hòa tăng cường"}, {"text": "or increased due to lack of sleep,", "start": 802.371, "duration": 2.458, "translation": "hoặc tăng lên do thiếu ngủ,"}, {"text": "were genes related to tumor development,", "start": 804.871, "duration": 3.75, "translation": "là các gen liên quan đến sự phát triển khối u,"}, {"text": "genes associated with chronic, long-term inflammation within the body,", "start": 808.662, "duration": 5.042, "translation": "các gen liên quan đến viêm mãn tính, kéo dài trong cơ thể,"}, {"text": "and genes associated with stress,", "start": 813.871, "duration": 2.666, "translation": "và các gen liên quan đến căng thẳng,"}, {"text": "and as a result, cardiovascular diseases.", "start": 817.037, "duration": 3.875, "translation": "và kết quả là, các bệnh tim mạch."}, {"text": "There is simply no aspect of your health", "start": 820.954, "duration": 3.25, "translation": "Đơn giản là không có khía cạnh nào trong sức khỏe của bạn"}, {"text": "that can withdraw when a sign of sleep deprivation appears", "start": 824.246, "duration": 4.041, "translation": "có thể rút lui khi dấu hiệu thiếu ngủ xuất hiện"}, {"text": "and escape unharmed.", "start": 828.287, "duration": 1.709, "translation": "và thoát khỏi mà không bị tổn hại."}, {"text": "It's somewhat like a broken water pipe in your home.", "start": 830.996, "duration": 2.666, "translation": "Điều đó hơi giống một đường ống nước bị vỡ trong nhà bạn."}, {"text": "Sleep deprivation will seep into every nook and cranny", "start": 833.704, "duration": 3.708, "translation": "Thiếu ngủ sẽ thấm vào mọi ngóc ngách"}, {"text": "of your organs,", "start": 837.412, "duration": 2.167, "translation": "trong các cơ quan của bạn,"}, {"text": "even the damage will reach the nuclear alphabet of your DNA", "start": 840.037, "duration": 3.959, "translation": "thậm chí sự phá hoại sẽ lan đến bảng chữ cái hạt nhân của DNA"}, {"text": "which tells the story of your daily health.", "start": 844.496, "duration": 4.166, "translation": "kể câu chuyện về sức khỏe hàng ngày của bạn."}, {"text": "At this point, you might be wondering:", "start": 849.662, "duration": 1.542, "translation": "Đến đây, bạn có thể tự hỏi:"}, {"text": "\\"Oh my, how can I improve my sleep?", "start": 851.204, "duration": 4.167, "translation": "\\"Ôi trời, làm thế nào tôi có thể cải thiện giấc ngủ của mình?"}, {"text": "What are your tips for good sleep?\\"", "start": 855.371, "duration": 2.791, "translation": "Lời khuyên của bạn để có giấc ngủ ngon là gì?"}, {"text": "In addition to avoiding the dangerous and destructive effects", "start": 858.287, "duration": 4.334, "translation": "Ngoài việc tránh những tác động nguy hiểm và tàn phá"}, {"text": "of alcohol and caffeine on sleep,", "start": 862.662, "duration": 2.125, "translation": "của rượu và caffeine đối với giấc ngủ,"}, {"text": "and if you struggle to sleep at night,", "start": 864.787, "duration": 3.25, "translation": "và nếu bạn gặp khó khăn khi ngủ vào ban đêm,"}, {"text": "Avoid naps during the day.", "start": 868.079, "duration": 1.792, "translation": "Tránh ngủ trưa trong ngày."}, {"text": "I have two tips for you.", "start": 869.912, "duration": 2.084, "translation": "Tôi có hai lời khuyên dành cho bạn."}, {"text": "The first tip is consistency.", "start": 872.746, "duration": 2.708, "translation": "Lời khuyên đầu tiên là sự nhất quán."}, {"text": "Go to bed and wake up at the same time,", "start": 875.454, "duration": 3.958, "translation": "Đi ngủ và thức dậy vào cùng một thời điểm,"}, {"text": "whether it's a weekday or a weekend.", "start": 879.537, "duration": 2.334, "translation": "dù là ngày thường hay cuối tuần."}, {"text": "Consistency is excellent.", "start": 881.996, "duration": 2.541, "translation": "Sự nhất quán là rất quan trọng."}, {"text": "It will guide your sleep", "start": 884.787, "duration": 2.417, "translation": "Nó sẽ điều chỉnh giấc ngủ của bạn"}, {"text": "and improve the quality and quantity of your sleep.", "start": 887.287, "duration": 3.875, "translation": "và cải thiện cả chất lượng lẫn số lượng giấc ngủ của bạn."}, {"text": "The second tip is to keep your room cool.", "start": 892.204, "duration": 3.333, "translation": "Lời khuyên thứ hai là giữ phòng mát mẻ."}, {"text": "Your body needs to lower its core temperature", "start": 895.829, "duration": 3, "translation": "Cơ thể bạn cần hạ nhiệt độ cốt lõi của nó"}, {"text": "by about one to one and a half degrees Celsius", "start": 898.871, "duration": 3.583, "translation": "khoảng một đến một rưỡi độ C"}, {"text": "in order to initiate and then maintain sleep.", "start": 902.454, "duration": 1.583, "translation": "để bắt đầu và sau đó duy trì giấc ngủ."}, {"text": "This is why you'll find it easier to sleep", "start": 904.037, "duration": 4.75, "translation": "Đây là lý do tại sao bạn sẽ thấy dễ ngủ hơn"}, {"text": "in a very cool room", "start": 908.787, "duration": 1.292, "translation": "trong một căn phòng rất mát mẻ"}, {"text": "compared to a very warm room.", "start": 910.079, "duration": 2.042, "translation": "so với một căn phòng rất nóng."}, {"text": "So, choose a room with a temperature of 65 degrees Fahrenheit", "start": 912.204, "duration": 3.5, "translation": "Vì vậy, hãy chọn một căn phòng có nhiệt độ 65 độ F"}, {"text": "or about 18 degrees Celsius.", "start": 915.746, "duration": 1.875, "translation": "hoặc khoảng 18 độ C."}, {"text": "This will be ideal for sleep for most people.", "start": 917.662, "duration": 3.375, "translation": "Đây sẽ là nhiệt độ lý tưởng để ngủ đối với hầu hết mọi người."}, {"text": "Finally, if we pause for a moment and think deeply:", "start": 922.537, "duration": 3.5, "translation": "Cuối cùng, nếu chúng ta dừng lại một chút và suy nghĩ kỹ:"}, {"text": "What is the key takeaway here?", "start": 926.121, "duration": 4.416, "translation": "Ý chính ở đây là gì?"}, {"text": "I think it's this:", "start": 930.579, "duration": 2, "translation": "Tôi nghĩ đó là điều này:"}, {"text": "Unfortunately, sleep is not a luxury.", "start": 932.996, "duration": 5.666, "translation": "Thật không may, giấc ngủ không phải là một thứ xa xỉ."}, {"text": "Sleep is an absolute biological necessity.", "start": 938.704, "duration": 5.917, "translation": "Giấc ngủ là một nhu cầu sinh học tuyệt đối."}, {"text": "It's the system that keeps you alive,", "start": 944.704, "duration": 3.75, "translation": "Đó là hệ thống giúp bạn sống sót,"}, {"text": "and it's Mother Nature's greatest effort for immortality to date.", "start": 948.454, "duration": 4.542, "translation": "và đó là nỗ lực vĩ đại nhất của Mẹ Thiên nhiên cho sự bất tử cho đến nay."}, {"text": "And sleep deprivation in all industrialized nations", "start": 954.829, "duration": 4.375, "translation": "Và tình trạng thiếu ngủ ở tất cả các quốc gia công nghiệp hóa"}, {"text": "has a catastrophic effect on our health and well-being,", "start": 959.246, "duration": 4.208, "translation": "có tác động thảm khốc đến sức khỏe và hạnh phúc của chúng ta,"}, {"text": "and even on the integrity of our children's education.", "start": 963.621, "duration": 3.791, "translation": "và thậm chí cả sự toàn vẹn trong giáo dục của con cái chúng ta."}, {"text": "It's a sleep loss epidemic.", "start": 968.246, "duration": 2.958, "translation": "Đó là một dịch bệnh thiếu ngủ."}, {"text": "And it has become one of the greatest health challenges", "start": 971.371, "duration": 3.708, "translation": "Và nó đã trở thành một trong những thách thức sức khỏe lớn nhất"}, {"text": "that we face in the 21st century.", "start": 975.162, "duration": 2.5, "translation": "mà chúng ta phải đối mặt trong thế kỷ 21."}, {"text": "I think the time has come for us to reclaim our right", "start": 980.287, "duration": 5.167, "translation": "Tôi nghĩ đã đến lúc chúng ta đòi lại quyền của mình"}, {"text": "to full hours of sleep,", "start": 985.496, "duration": 2.833, "translation": "được ngủ đủ giấc,"}, {"text": "and without embarrassment,", "start": 988.329, "duration": 2.042, "translation": "và không chút ngượng ngùng,"}, {"text": "and without that unfortunate stigma of laziness.", "start": 990.454, "duration": 4.125, "translation": "và không có sự kỳ thị đáng tiếc về sự lười biếng đó."}, {"text": "And by doing so, we can unite with the most powerful elixir of immortality,", "start": 994.871, "duration": 6.541, "translation": "Và bằng cách đó, chúng ta có thể kết hợp với loại thuốc trường sinh mạnh mẽ nhất,"}, {"text": "the Swiss Army knife of health, so to speak.", "start": 1002.246, "duration": 3.541, "translation": "con dao đa năng Thụy Sĩ của sức khỏe, nếu có thể nói như vậy."}, {"text": "And having spoken to you from this platform,", "start": 1005.871, "duration": 3.708, "translation": "Và sau khi đã phát biểu với quý vị từ bục này,"}, {"text": "I will simply say, good evening, good luck,", "start": 1009.579, "duration": 2, "translation": "tôi sẽ đơn giản nói, chúc quý vị một buổi tối tốt lành, chúc may mắn,"}, {"text": "And most importantly...", "start": 1011.662, "duration": 0.875, "translation": "Và quan trọng nhất..."}, {"text": "I hope you sleep well.", "start": 1014.829, "duration": 1.792, "translation": "Tôi hy vọng các bạn ngủ ngon."}, {"text": "Thank you very much.", "start": 1016.662, "duration": 1.167, "translation": "Cảm ơn các bạn rất nhiều."}, {"text": "(Applause)", "start": 1017.829, "duration": 5, "translation": "(Tiếng vỗ tay)"}, {"text": "Thank you.", "start": 1022.829, "duration": 1.083, "translation": "Cảm ơn các bạn."}, {"text": "(Applause)", "start": 1023.912, "duration": 2.417, "translation": "(Tiếng vỗ tay)"}, {"text": "Thank you very much.", "start": 1026.371, "duration": 1.708, "translation": "Cảm ơn rất nhiều."}, {"text": "David Bello: No, no, no. Stay where you are for one second.", "start": 1028.204, "duration": 2.709, "translation": "David Bello: Không, không, không. Đứng yên đó một giây."}, {"text": "Good job you didn't run away. I appreciate that.", "start": 1030.954, "duration": 2.084, "translation": "Tốt lắm vì bạn đã không bỏ chạy. Tôi đánh giá cao điều đó."}, {"text": "So, that was terrifying.", "start": 1033.121, "duration": 1.708, "translation": "Vậy thì, điều đó thật đáng sợ."}, {"text": "Matthew Walker: You're welcome. David: Yes, thank you, thank you.", "start": 1034.913, "duration": 3.375, "translation": "Matthew Walker: Không có gì. David: Vâng, cảm ơn, cảm ơn."}, {"text": "Since we cannot catch up on lost sleep, what should we do?", "start": 1038.413, "duration": 5.5, "translation": "Vì chúng ta không thể ngủ bù, vậy chúng ta nên làm gì?"}, {"text": "What do we do when we toss and turn in bed at night,", "start": 1043.913, "duration": 2.791, "translation": "Chúng ta làm gì khi trằn trọc trên giường vào ban đêm,"}, {"text": "or work shifts, or anything else?", "start": 1046.746, "duration": 3.583, "translation": "hoặc làm việc theo ca, hay bất cứ điều gì khác?"}, {"text": "Matthew: You're right, we cannot catch up on lost sleep.", "start": 1050.329, "duration": 2.459, "translation": "Matthew: Bạn nói đúng, chúng ta không thể ngủ bù."}, {"text": "Sleep is not a pile.", "start": 1052.788, "duration": 1.208, "translation": "Giấc ngủ không phải là một đống."}, {"text": "You cannot accumulate debt.", "start": 1053.996, "duration": 1.833, "translation": "Bạn không thể tích lũy nợ."}, {"text": "Then hope to pay it at a specific time.", "start": 1055.829, "duration": 2.875, "translation": "Rồi hy vọng sẽ trả nó vào một thời điểm cụ thể."}, {"text": "I must also point out the reason why that is catastrophic", "start": 1058.746, "duration": 4.083, "translation": "Tôi cũng phải chỉ ra lý do tại sao điều đó lại tai hại"}, {"text": "and makes our health deteriorate rapidly.", "start": 1062.871, "duration": 1.875, "translation": "và khiến sức khỏe của chúng ta suy giảm nhanh chóng."}, {"text": "First, because humans are the only species", "start": 1064.746, "duration": 3.333, "translation": "Thứ nhất, bởi vì con người là loài duy nhất"}, {"text": "Those who deprive themselves of sleep.", "start": 1068.121, "duration": 2, "translation": "Những người tự tước đoạt giấc ngủ của mình."}, {"text": "Without any clear reason.", "start": 1070.163, "duration": 1.125, "translation": "Mà không có bất kỳ lý do rõ ràng nào."}, {"text": "David: Because we're smart.", "start": 1071.996, "duration": 1.292, "translation": "David: Bởi vì chúng ta thông minh."}, {"text": "Matthew: I say this because it means that Mother Nature", "start": 1073.329, "duration": 5.084, "translation": "Matthew: Tôi nói điều này bởi vì nó có nghĩa là Mẹ Thiên nhiên"}, {"text": "during the evolutionary path", "start": 1078.538, "duration": 1.833, "translation": "trong suốt quá trình tiến hóa"}, {"text": "didn't have the chance to confront this danger called sleep deprivation.", "start": 1080.538, "duration": 4.75, "translation": "đã không có cơ hội đối mặt với mối nguy hiểm mang tên thiếu ngủ này."}, {"text": "So it didn't develop a safety net,", "start": 1085.329, "duration": 2.625, "translation": "Vì vậy, nó đã không phát triển một mạng lưới bảo vệ,"}, {"text": "And for this reason, if you don't get enough sleep,", "start": 1087.996, "duration": 3.208, "translation": "Và vì lý do này, nếu bạn không ngủ đủ giấc,"}, {"text": "things will collapse within both your mind and body.", "start": 1091.288, "duration": 4.208, "translation": "mọi thứ sẽ sụp đổ trong cả tâm trí và cơ thể bạn."}, {"text": "So you just have to prioritize things.", "start": 1095.663, "duration": 2.416, "translation": "Vì vậy, bạn chỉ cần ưu tiên mọi thứ."}, {"text": "David: Okay, but if I'm tossing and turning in bed,", "start": 1098.204, "duration": 2.834, "translation": "David: Được rồi, nhưng nếu tôi trằn trọc trên giường,"}, {"text": "what should I do?", "start": 1101.038, "duration": 1.958, "translation": "tôi nên làm gì?"}, {"text": "Matthew: If you're tossing and turning in bed, wide awake for a long time,", "start": 1102.996, "duration": 4.583, "translation": "Matthew: Nếu bạn trằn trọc trên giường, thức trắng trong một thời gian dài,"}, {"text": "you should get out of bed and go to another room", "start": 1107.621, "duration": 3.25, "translation": "bạn nên ra khỏi giường và đi sang phòng khác"}, {"text": "and do something different.", "start": 1110.913, "duration": 1.458, "translation": "và làm điều gì đó khác."}, {"text": "The reason for this is that your brain will quickly associate your bedroom", "start": 1112.413, "duration": 4, "translation": "Lý do là bộ não của bạn sẽ nhanh chóng liên kết phòng ngủ của bạn"}, {"text": "with being awake.", "start": 1116.496, "duration": 2.208, "translation": "với việc thức giấc."}, {"text": "So you need to break this association.", "start": 1118.829, "duration": 2.959, "translation": "Vì vậy, bạn cần phá vỡ sự liên kết này."}, {"text": "Only go back to bed when you're sleepy,", "start": 1121.954, "duration": 2.542, "translation": "Chỉ trở lại giường khi bạn đã buồn ngủ,"}, {"text": "and in this way, you will have re-established the association you had.", "start": 1124.579, "duration": 3.209, "translation": "và bằng cách này, bạn sẽ tái thiết lập được sự liên kết mà bạn đã có."}, {"text": "The bed is for sleeping.", "start": 1127.829, "duration": 2.375, "translation": "Giường là nơi để ngủ."}, {"text": "So, the comparison is:", "start": 1130.329, "duration": 2.084, "translation": "Vậy thì, sự so sánh là:"}, {"text": "You would never sit at the dining table waiting to get hungry,", "start": 1132.454, "duration": 3.5, "translation": "Bạn sẽ không bao giờ ngồi vào bàn ăn chờ đợi để đói bụng,"}, {"text": "So why would you lie on your bed waiting to get sleepy?", "start": 1136.038, "duration": 3.583, "translation": "Vậy thì tại sao bạn lại nằm trên giường chờ đợi để buồn ngủ?"}, {"text": "David: Thank you for the advice.", "start": 1139.663, "duration": 1.791, "translation": "David: Cảm ơn bạn vì lời khuyên này."}, {"text": "Great job, Matt.", "start": 1141.454, "duration": 1, "translation": "Làm tốt lắm, Matt."}, {"text": "Matthew: You're welcome. Thank you very much.", "start": 1142.454, "duration": 2.917, "translation": "Matthew: Không có gì. Cảm ơn bạn rất nhiều."}]	2026-05-08 06:55:41.822+00
